+    let mut bad = file();
+    bad["kinematics"]["default"]["parts"].as_array_mut().unwrap()
+        .push(json!({"name":"A", "type":"rotary"}));
+    assert!(machine::validate::validate_text(&bad.to_string()).iter().any(|e| e.key == "A"));
